def _interpolate(
    sections: dict[str, dict[str, str]],
) -> dict[str, dict[str, str]]:
    """Interpolate every value in *sections*, preserving their order."""
    cache: dict[tuple[str, str], str] = {}
    stack: list[tuple[str, str]] = []
    active: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        location = (section, key)
        if location in cache:
            return cache[location]
        if location in active:
            cycle = stack[stack.index(location):] + [location]
            description = " -> ".join(
                f"[{sec}] {name}" for sec, name in cycle
            )
            raise InterpolationError(f"interpolation cycle: {description}")
        if section not in sections:
            raise InterpolationError(f"missing section {section!r}")
        if key not in sections[section]:
            raise InterpolationError(
                f"missing key {key!r} in section {section!r}"
            )

        active.add(location)
        stack.append(location)
        try:
            value = _expand(sections[section][key], section, resolve)
        finally:
            stack.pop()
            active.remove(location)
        cache[location] = value
        return value

    return {
        section: {key: resolve(section, key) for key in values}
        for section, values in sections.items()
    }


def _expand(
    text: str,
    section: str,
    resolve: "Callable[[str, str], str]",
) -> str:
    """Expand references in one value, without rescanning literal dollars."""
    pieces: list[str] = []
    i = 0
    length = len(text)
    while i < length:
        char = text[i]
        if char != "$":
            pieces.append(char)
            i += 1
            continue

        if i + 1 < length and text[i + 1] == "$":
            # A doubled dollar is a literal dollar, and is not rescanned.
            pieces.append("$")
            i += 2
            continue

        if i + 1 < length and text[i + 1] == "{":
            closing = text.find("}", i + 2)
            if closing == -1:
                # A malformed opening is just an ordinary dollar sign.
                pieces.append("$")
                i += 1
                continue
            reference = text[i + 2 : closing]
            if ":" in reference:
                ref_section, ref_key = reference.split(":", 1)
                ref_section = ref_section.strip()
            else:
                ref_section = section
                ref_key = reference
            ref_key = ref_key.strip().lower()
            pieces.append(resolve(ref_section, ref_key))
            i = closing + 1
            continue

        # Any other dollar sign is left alone.
        pieces.append("$")
        i += 1

    return "".join(pieces)


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    current_key: str | None = None
    can_continue = False

    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()

        # Blank lines and comments are ignored, and end any continuation.
        if not stripped or stripped[0] in "#;":
            can_continue = False
            current_key = None
            continue

        # A whitespace-led line continues a value only when it directly
        # follows a key line or another continuation line.
        if line[:1].isspace() and can_continue and current_key is not None:
            assert current_section is not None
            sections[current_section][current_key] += "\n" + stripped
            continue

        can_continue = False
        current_key = None

        if stripped.startswith("[") and stripped.endswith("]"):
            section = stripped[1:-1].strip()
            sections.setdefault(section, {})
            current_section = section
            continue

        equals = stripped.find("=")
        colon = stripped.find(":")
        if equals == -1:
            split = colon
        elif colon == -1:
            split = equals
        else:
            split = min(equals, colon)

        if split == -1:
            raise ParseError(lineno, "unrecognized line")

        key = stripped[:split].strip().lower()
        value = stripped[split + 1 :].strip()

        if not key:
            raise ParseError(lineno, "empty key")
        if current_section is None:
            raise ParseError(lineno, "key before section")

        sections[current_section][key] = value
        current_key = key
        can_continue = True

    return _interpolate(sections)

