import sys

sys.path.insert(0, "/private/tmp/tmp5uk5a2ge/pete/projects/devkit")
from devkit.ini import InterpolationError, ParseError, parse

# Extra ordering / duplicate checks
assert list(parse("[b]\nx=1\n[a]\ny=2\n[b]\nz=3\n")) == ["b", "a"]
r = parse("[a]\nx=1\ny=2\nx=3\n")
assert list(r["a"]) == ["x", "y"] and r["a"]["x"] == "3"

# Value separators and comments
assert parse("[a]\nurl = http://x/y\nnote = a;b # c\n") == {
    "a": {"url": "http://x/y", "note": "a;b # c"}
}

# Whitespace-led section line directly after a key continues that key.
assert parse("[a]\nk=v\n  [b]\n") == {"a": {"k": "v\n[b]"}}

# Recursive cross-section interpolation with multiple levels.
assert parse("[a]\nx=${b:y}\n[b]\ny=${c:z}\n[c]\nz=ok\n")["a"]["x"] == "ok"

# $$ literal in a referenced value survives when the reference is reused.
r = parse("[a]\nx=$${y}\np=${x}\nq=${x}\n")
assert r["a"] == {"x": "${y}", "p": "${y}", "q": "${y}"}

# Malformed and unknown dollar forms.
assert parse("[a]\na=$b\nb=${no-close\nc=$\nd=$$$e\n")["a"] == {
    "a": "$b",
    "b": "${no-close",
    "c": "$",
    "d": "$",
}

# Error line numbers after multi-line values.
try:
    parse("[a]\nk=v\n  cont\n\njunk\n")
except ParseError as e:
    assert e.lineno == 5 and str(e) == "line 5: unrecognized line"
else:
    raise AssertionError("expected ParseError")

# Cycle across a continued value.
try:
    parse("[a]\nx=${y}\n  tail\ny=${x}\n")
except InterpolationError as e:
    assert "cycle" in str(e)
else:
    raise AssertionError("expected InterpolationError")

print("extra edge checks passed")
